1	/**
2	 * สร้างข้อมูลตั้งต้น — ประวัติการใช้งานย้อนหลัง 3 เดือน (พฤษภาคม–กรกฎาคม 2026)
3	 *
4	 * ใช้ตัวสุ่มที่กำหนด seed ไว้ จึงได้ข้อมูลชุดเดิมทุกครั้งที่รัน
5	 * ข้อมูลนี้คือ "ใบแจ้งหนี้ที่ออกไปแล้ว" ของเดือนที่ผ่านมา
6	 *
7	 *   node seed.ts
8	 */
9	
10	import type { DomainEvent, Role } from './src/domain/events.ts';
11	import { resetStore, eventLogPath } from './src/store/eventStore.ts';
12	import { totalRevenueForMonth } from './src/projections/billing.ts';
13	import { loadEvents } from './src/store/eventStore.ts';
14	
15	function makeRng(seed: number) {
16	  let x = seed >>> 0 || 1, y = 362436069, z = 521288629, w = 88675123;
17	  return () => {
18	    const t = x ^ (x << 11);
19	    x = y; y = z; z = w;
20	    w = (w ^ (w >>> 19)) ^ (t ^ (t >>> 8));
21	    return (w >>> 0) / 4294967296;
22	  };
23	}
24	
25	const USERS: { id: string; role: Role }[] = [
26	  { id: 'u-somchai', role: 'PHD_STUDENT' },
27	  { id: 'u-nadia', role: 'PHD_STUDENT' },
28	  { id: 'u-pat', role: 'STUDENT' },
29	  { id: 'u-ming', role: 'STUDENT' },
30	  { id: 'u-arun', role: 'LECTURER' },
31	  { id: 'u-kanya', role: 'LECTURER' },
32	  { id: 'u-admin', role: 'LAB_ADMIN' },
33	];
34	
35	const RESOURCE_IDS = ['gpu-a100-01', 'gpu-a100-02', 'gpu-v100-01', 'gpu-v100-02'];
36	
37	const iso = (d: Date) => d.toISOString();
38	const addMin = (d: Date, m: number) => new Date(d.getTime() + m * 60000);
39	
40	function build(): DomainEvent[] {
41	  const rnd = makeRng(20260804);
42	  const events: DomainEvent[] = [];
43	  let n = 0;
44	
45	  // ไล่ทีละวันตั้งแต่ 1 พ.ค. ถึง 31 ก.ค. 2026
46	  const start = new Date('2026-05-01T00:00:00.000Z');
47	  const days = 92;
48	
49	  for (let d = 0; d < days; d++) {
50	    const bookingsToday = rnd() < 0.35 ? 0 : 1 + Math.floor(rnd() * 2);
51	    for (let k = 0; k < bookingsToday; k++) {
52	      n += 1;
53	      const user = USERS[Math.floor(rnd() * (USERS.length - 1))]; // ไม่รวม admin
54	      const resourceId = RESOURCE_IDS[Math.floor(rnd() * RESOURCE_IDS.length)];
55	      const bookingId = `bk-seed-${String(n).padStart(3, '0')}`;
56	
57	      const dayStart = new Date(start.getTime() + d * 86400000);
58	      const startHour = 8 + Math.floor(rnd() * 9);
59	      const startAt = new Date(dayStart);
60	      startAt.setUTCHours(startHour, k * 15, 0, 0);
61	
62	      // ระยะเวลาที่จอง เป็นจำนวนเท่าของ 15 นาที ตาม REQ-04
63	      const blocks = 4 + Math.floor(rnd() * 12);          // 1 ถึง 4 ชม.
64	      const endAt = addMin(startAt, blocks * 15);
65	      const bookedHours = (blocks * 15) / 60;
66	      const requiresApproval = bookedHours > 8;
67	
68	      const requestedAt = addMin(startAt, -(60 + Math.floor(rnd() * 2880)));
69	      events.push({
70	        type: 'BookingRequested', bookingId, occurredAt: iso(requestedAt), actorId: user.id,
71	        userId: user.id, userRole: user.role, resourceId,
72	        startAt: iso(startAt), endAt: iso(endAt), requiresApproval,
73	      });
74	
75	      if (requiresApproval) {
76	        events.push({ type: 'BookingApproved', bookingId, occurredAt: iso(addMin(requestedAt, 30)), actorId: 'u-admin' });
77	      }
78	
79	      const roll = rnd();
80	
81	      if (roll < 0.12) {
82	        // จองแล้วไม่มาใช้ — ยังไม่มีเหตุการณ์ NoShow ในระบบ จึงค้างสถานะไว้
83	        continue;
84	      }
85	
86	      // เริ่มใช้งานช้ากว่าเวลาที่จองเล็กน้อย
87	      const actualStartAt = addMin(startAt, Math.floor(rnd() * 12));
88	      events.push({
89	        type: 'BookingStarted', bookingId, occurredAt: iso(actualStartAt),
90	        actorId: user.id, actualStartAt: iso(actualStartAt),
91	      });
92	
93	      if (roll < 0.2) continue;   // ค้างสถานะกำลังใช้งาน (ยังไม่ complete)
94	
95	      // เลิกใช้ก่อนเวลาเล็กน้อย และ "จงใจให้ไม่ลงตัว 15 นาที"
96	      // เพื่อให้การปัดขึ้นกับปัดลงให้ผลต่างกันจริง
97	      const usedMinutes = blocks * 15 - (1 + Math.floor(rnd() * 20));
98	      const actualEndAt = addMin(actualStartAt, Math.max(5, usedMinutes));
99	      events.push({
100	        type: 'BookingCompleted', bookingId, occurredAt: iso(actualEndAt),
101	        actorId: user.id, actualEndAt: iso(actualEndAt),
102	      });
103	    }
104	  }
105	
106	  return events.sort((a, b) => a.occurredAt.localeCompare(b.occurredAt));
107	}
108	
109	const events = build();
