    });
    assert.equal(buildInvoice(events, 'u-pat', '2026-05').totalBaht, 80);   // 2 ชม. ไม่ใช่ 8
  });

  test('REQ-35 เศษนาทีถูกปัดขึ้นก่อนคิดเงิน', () => {
